package com.example.starter.config;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

import java.time.Clock;

/**
 * 应用基础配置：提供可替换的时钟，测试中以可控时钟覆盖。
 */
@Configuration
public class AppConfig {

    /**
     * 系统时钟 Bean；生产环境使用系统默认时区时钟。
     */
    @Bean
    public Clock clock() {
        return Clock.systemDefaultZone();
    }
}

package com.example.starter.domain;

/**
 * 展示池状态：NORMAL 正常，ALARM 告警，EMERGENCY 紧急（连续3点越限），DISPOSING 处置中（暂停展示登记）。
 */
public enum ZoneStatus {
    NORMAL,
    ALARM,
    EMERGENCY,
    DISPOSING
}

package com.example.starter.domain;

/**
 * 传感器状态：ONLINE 在线，MISSING 失联数据缺失（挂起自动处置），PENDING_CONFIRM 复连待人工确认补算。
 */
public enum SensorState {
    ONLINE,
    MISSING,
    PENDING_CONFIRM
}

package com.example.starter.domain;

/**
 * 告警状态：OPEN 未升级，ESCALATED 已升级为紧急，RESOLVED 已解除。
 */
public enum AlarmStatus {
    OPEN,
    ESCALATED,
    RESOLVED
}

package com.example.starter.domain;

/**
 * 处置指令类型：AERATION 增氧，WATER_CHANGE 换水，CLOSURE_ISOLATION 停展隔离。
 */
public enum CommandType {
    AERATION,
    WATER_CHANGE,
    CLOSURE_ISOLATION;

    /**
     * 超时升级后的下一级指令类型；停展隔离已为最高级，升级后仍为停展隔离。
     */
    public CommandType next() {
        return switch (this) {
            case AERATION -> WATER_CHANGE;
            case WATER_CHANGE -> CLOSURE_ISOLATION;
            case CLOSURE_ISOLATION -> CLOSURE_ISOLATION;
        };
    }
}

package com.example.starter.domain;

/**
 * 处置指令状态：PENDING 待回执，CONFIRMED 已确认，ESCALATED 回执超时已升级，COMPLETED 恢复后完成。
 */
public enum CommandStatus {
    PENDING,
    CONFIRMED,
    ESCALATED,
    COMPLETED
}

package com.example.starter.domain;

/**
 * 展示池事件类型，用于日评估复算告警处置链与稳定时长。
 */
public enum EventType {
    /** 池状态变更 */
    STATUS_CHANGE,
    /** 告警产生 */
    ALARM_RAISED,
    /** 处置指令下发 */
    COMMAND_ISSUED,
    /** 处置回执确认 */
    COMMAND_CONFIRMED,
    /** 回执超时升级 */
    COMMAND_ESCALATED,
    /** 传感器失联，数据缺失 */
    SENSOR_MISSING,
    /** 传感器复连，待人工确认 */
    SENSOR_RECONNECTED,
    /** 人工确认复连并补算 */
    SENSOR_CONFIRMED,
    /** 复测合格恢复 */
    RECOVERY
}

