        ZonePool updated = new ZonePool(zone.id(), zone.code(), zone.name(), status, consecutive,
                zone.sensorState(), zone.lastHeartbeatAt(), zone.missingSince(), now);
        zoneRepository.updateState(updated);
        return updated;
    }
}

