package com.example.starter.service;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;

/**
 * 定时维护服务：统一驱动回执超时升级与传感器失联判定，供调度或手动触发。
 */
@Service
public class MaintenanceService {

    private final DisposalService disposalService;
    private final SensorService sensorService;

    public MaintenanceService(DisposalService disposalService, SensorService sensorService) {
        this.disposalService = disposalService;
        this.sensorService = sensorService;
    }

    /**
     * 维护节拍结果。
     *
     * @param escalatedCommands 本次升级的回执超时指令数
     * @param missingSensors    本次新标记失联的传感器数
     */
    public record TickResult(int escalatedCommands, int missingSensors) {
    }

    /**
     * 执行一次维护节拍：先处理回执超时升级，再判定传感器失联。
     */
    @Transactional
    public TickResult tick(LocalDateTime now) {
        int escalated = disposalService.processTimeouts(now);
        int missing = sensorService.checkLoss(now);
        return new TickResult(escalated, missing);
    }
}

package com.example.starter.service;

import com.example.starter.domain.Alarm;
import com.example.starter.domain.DisposalCommand;
import com.example.starter.domain.ZoneEvent;
import com.example.starter.domain.ZonePool;
import com.example.starter.domain.ZoneStatus;
import com.example.starter.repo.AlarmRepository;
import com.example.starter.repo.DisposalRepository;
import com.example.starter.repo.EventRepository;
import com.example.starter.repo.ZoneRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Duration;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.List;

/**
 * 日评估服务：输出各池稳定时长与告警处置链；纯事件流水推导，可重复复算。
 */
@Service
public class EvaluationService {

    private final ZoneRepository zoneRepository;
    private final EventRepository eventRepository;
    private final AlarmRepository alarmRepository;
    private final DisposalRepository disposalRepository;

    public EvaluationService(ZoneRepository zoneRepository, EventRepository eventRepository,
                             AlarmRepository alarmRepository, DisposalRepository disposalRepository) {
        this.zoneRepository = zoneRepository;
        this.eventRepository = eventRepository;
        this.alarmRepository = alarmRepository;
        this.disposalRepository = disposalRepository;
    }

    /**
     * 单池日评估结果。
     *
     * @param stableSeconds 当日 NORMAL 状态累计时长（秒）
     */
    public record ZoneEvaluation(String zoneCode, String zoneName, long stableSeconds,
                                 List<AlarmChain> alarms) {
    }

    /**
     * 告警及其处置指令链。
     */
    public record AlarmChain(long alarmId, String params, String detail, String status,
                             LocalDateTime createdAt, List<CommandLink> commands) {
    }

    /**
     * 处置指令链节。
     */
    public record CommandLink(long commandId, String commandType, String status,
                              LocalDateTime createdAt, LocalDateTime confirmedAt,
                              LocalDateTime escalatedAt) {
    }

    /**
     * 复算指定日期的全部展示池评估。
     */
    @Transactional(readOnly = true)
    public List<ZoneEvaluation> evaluate(LocalDate date) {
        LocalDateTime dayStart = date.atStartOfDay();
        LocalDateTime dayEnd = date.plusDays(1).atStartOfDay();
        List<ZoneEvaluation> result = new ArrayList<>();
        for (ZonePool zone : zoneRepository.listAll()) {
            long stableSeconds = computeStableSeconds(zone.id(), dayStart, dayEnd);
            List<AlarmChain> chains = new ArrayList<>();
            for (Alarm alarm : alarmRepository.findByZone(zone.id())) {
                if (alarm.createdAt().isBefore(dayStart) || !alarm.createdAt().isBefore(dayEnd)) {
                    continue;
                }
                List<CommandLink> commands = new ArrayList<>();
                for (DisposalCommand command : disposalRepository.findByZone(zone.id())) {
                    if (command.alarmId() == alarm.id()) {
                        commands.add(new CommandLink(command.id(), command.commandType().name(),
                                command.status().name(), command.createdAt(), command.confirmedAt(),
                                command.escalatedAt()));
                    }
                }
                chains.add(new AlarmChain(alarm.id(), alarm.params(), alarm.detail(),
                        alarm.status().name(), alarm.createdAt(), commands));
            }
            result.add(new ZoneEvaluation(zone.code(), zone.name(), stableSeconds, chains));
        }
        return result;
    }

    /**
     * 依据状态变更事件流水累计当日 NORMAL 时长；区间起点状态取此前最近一次状态事件，缺省 NORMAL。
     */
    private long computeStableSeconds(long zoneId, LocalDateTime dayStart, LocalDateTime dayEnd) {
        ZoneStatus current = eventRepository.findLastStatusEventBefore(zoneId, dayStart)
                .map(event -> ZoneStatus.valueOf(event.toStatus()))
                .orElse(ZoneStatus.NORMAL);
        long stableSeconds = 0;
        LocalDateTime cursor = dayStart;
        for (ZoneEvent event : eventRepository.findStatusEventsBetween(zoneId, dayStart, dayEnd)) {
            if (current == ZoneStatus.NORMAL) {
                stableSeconds += Duration.between(cursor, event.occurredAt()).getSeconds();
            }
            current = ZoneStatus.valueOf(event.toStatus());
            cursor = event.occurredAt();
        }
        if (current == ZoneStatus.NORMAL) {
            stableSeconds += Duration.between(cursor, dayEnd).getSeconds();
        }
        return stableSeconds;
    }
}

content.thinking:
Services compile. Now the web layer: controllers + DTOs + exception handler. 

Design: each write endpoint wraps via IdempotencyService. The canonical payload = endpoint + business fields. Response body = JSON string. Controller returns ResponseEntity with the JSON string (200). For replayed requests, return same body with 200 (maybe header X-Idempotent-Replay — nice to have; skip, keep body).

Implementation approach in controllers: build canonical string like "zoneCode=..&do=..&nh3n=..&temp=..&sampledAt=..". Then:

```java
String body = idempotencyService.execute(req.requestId(), "sample", canonical, () -> {
    var result = monitoringService.ingest(...);
    return toJson(result);
});
return ResponseEntity.ok().contentType(APPLICATION_JSON).body(body);
```

toJson via ObjectMapper.

Note: BusinessException thrown inside action.get() propagates through IdempotencyService (not stored) — good, failures aren't cached. Hmm — should a 422 be cached? Spec doesn't say; standard: only successful results cached. Fine.

Wait — one issue: idempotency record insert and business action run in the same transaction (TransactionTemplate in IdempotencyService wraps action). Good — atomic.

But BusinessException inside txTemplate.execute → transaction rolls back → exception propagates. Good.

Controllers:

1. MonitoringController: POST /api/zones/{zoneCode}/samples
   Body: {requestId, dissolvedOxygen, ammoniaNitrogen, temperature, sampledAt?}
   sampledAt optional → default LocalDateTime.now(clock).

2. DisposalController: POST /api/disposals/{commandId}/receipt
   Body: {requestId, confirmedAt?}

3. ExhibitionController: POST /api/zones/{zoneCode}/exhibitions
   Body: {requestId, groupName, registeredAt?}

4. RecoveryController: POST /api/zones/{zoneCode}/recovery
   Body: {requestId, dissolvedOxygen, ammoniaNitrogen, temperature, testedAt?}

5. SensorController: POST /api/zones/{zoneCode}/sensor/heartbeat {requestId, at?}; POST /api/zones/{zoneCode}/sensor/reconnect-confirm {requestId, at?}

6. MaintenanceController: POST /api/maintenance/tick {now?}

7. EvaluationController: GET /api/evaluation/daily?date=yyyy-MM-dd

GlobalExceptionHandler: @RestControllerAdvice handling BusinessException → status + {"error": message}; MethodArgumentNotValidException / MissingServletRequestParameterException → 400.

Validation: use @Valid with jakarta validation annotations on request records (@NotBlank requestId, @NotNull values).

I'll write DTOs as nested records in each controller file to keep file count reasonable. Validation annotations on record components work.

Let me write the controllers now — one file per controller plus handler. That's 8 files. Write in two batches, then compile.

