/**
 * JSON 序列化辅助：将受检异常包装为运行时异常，便于在幂等执行的 lambda 中使用。
 */
@Component
public class JsonSupport {

    private final ObjectMapper objectMapper;

    public JsonSupport(ObjectMapper objectMapper) {
        this.objectMapper = objectMapper;
    }

